import { svgElement, pointsToString } from "./util.js";
//////////////////////////////////////////////////////////////////////////////////////////////////////////////
//polygon.isPointInFill(new DOMPoint(0, 0));
//////////////////////////////////////////////////////////////////////////////////////////////////////////////
function polygon(points, fill = "none", stroke = "black") {
    const attributes = {
        points: pointsToString(points, " ", " "),
        fill,
        stroke
    };
    return svgElement("polygon", attributes);
}
//////////////////////////////////////////////////////////////////////////////////////////////////////////////
export { polygon };
